/**
 * Security headers for responses generated by the Worker.
 *
 * The `_headers` file generated from this module at build time only applies to
 * static assets, so server-rendered event pages and API responses would
 * otherwise be served without these headers.
 */
import { CSP_HEADER_DIRECTIVES } from "~/shared/constants/security";

export const SECURITY_HEADERS: Readonly<Record<string, string>> = {
  "Content-Security-Policy": CSP_HEADER_DIRECTIVES.join("; "),
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "camera=(self), microphone=(), geolocation=()",
};

/** Copy the response so headers on immutable responses (e.g. redirects) can be set. */
export function withSecurityHeaders(response: Response): Response {
  const headers = new Headers(response.headers);

  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    if (!headers.has(name)) {
      headers.set(name, value);
    }
  }

  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}
